use kino_core::{color::{encode_contract,pipeline},commands::{Session,dispatch}};use serde_json::json;use std::process::Command;
#[test]fn exact_domains_fail_closed(){let mut q=pipeline::Pipeline::default();let c=encode_contract::high(&q,"hevc10").unwrap();assert_eq!((c.primaries,c.transfer_tag,c.matrix,c.range),("bt709","iec61966-2-1","bt709","tv"));q.enabled=true;for g in 0..8{for t in 0..9{q.output_gamut=g;q.output_transfer=t;let expected=g<=1&&([0,1,8].contains(&t)||g==1&&[6,7].contains(&t));assert_eq!(encode_contract::high(&q,"hevc10").is_ok(),expected);}}}
#[test]fn disabled_highbit_tags_and_precision(){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":32,"height":1024,"fps":25})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"gradient","color":[0.,0.,0.],"color2":[1.,1.,1.],"start":0,"duration":0.08})).unwrap();for format in ["hevc10","ffv1_16"]{let path=format!("/tmp/encode-contract-{}-{}.{}",std::process::id(),format,if format=="hevc10"{"mp4"}else{"mkv"});pipeline::export_high(&s.project,&path,format,0).unwrap();let probe=Command::new("ffprobe").args(["-v","error","-show_entries","stream=pix_fmt,color_range,color_space,color_transfer,color_primaries","-of","json",&path]).output().unwrap();let v:serde_json::Value=serde_json::from_slice(&probe.stdout).unwrap();let st=&v["streams"][0];assert_eq!(st["color_primaries"],"bt709");assert_eq!(st["color_transfer"],"iec61966-2-1");assert_eq!(st["color_range"],if format=="hevc10"{"tv"}else{"pc"});assert_eq!(st["color_space"],if format=="hevc10"{"bt709"}else{"gbr"});}}
